import React, { useEffect, useState } from 'react';
import { Card, api } from '../App';

const Stat = ({ label, value, color = '#1a3c5e', sub }) => (
  <div style={{ background:'#fff', borderRadius:10, padding:'20px 24px', boxShadow:'0 1px 4px rgba(0,0,0,0.08)', flex:1, minWidth:130 }}>
    <div style={{ fontSize:32, fontWeight:700, color, fontFamily:'Georgia,serif' }}>{value ?? '—'}</div>
    <div style={{ fontSize:13, color:'#555', marginTop:6, fontWeight:600 }}>{label}</div>
    {sub && <div style={{ fontSize:11, color:'#999', marginTop:2 }}>{sub}</div>}
  </div>
);

export default function Dashboard() {
  const [stats, setStats]     = useState(null);
  const [logs, setLogs]       = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([
      api.get('/reports/dashboard-full').catch(() => ({ data: {} })),
      api.get('/import/logs').catch(() => ({ data: [] }))
    ]).then(([d, l]) => {
      setStats(d.data);
      setLogs(l.data);
    }).finally(() => setLoading(false));
  }, []);

  if (loading) return <div style={{ padding:40, color:'#999' }}>Loading…</div>;

  return (
    <div>
      <h2 style={{ marginBottom:4, color:'#1a3c5e' }}>🍵 Tea Auction Dashboard</h2>
      <p style={{ color:'#888', fontSize:13, marginBottom:20 }}>Live overview from imported data</p>

      {/* Main stats */}
      <div style={{ display:'flex', gap:14, marginBottom:20, flexWrap:'wrap' }}>
        <Stat label="Total Parties"      value={stats?.total_parties}       color="#1a3c5e" sub="Registered" />
        <Stat label="Gardens"            value={stats?.total_gardens}       color="#1a7a4a" sub="From catalogue" />
        <Stat label="Grades"             value={stats?.total_grades}        color="#b45309" sub="Unique grades" />
        <Stat label="Marks"              value={stats?.total_marks}         color="#6d28d9" sub="Unique marks" />
        <Stat label="Catalogue Lots"     value={stats?.total_lots}          color="#0f766e" sub={stats?.latest_sale ? `Sale ${stats.latest_sale}` : 'Current'} />
        <Stat label="Confirmed Markings" value={stats?.confirmed_markings}  color="#c0392b" sub="This week" />
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:16, marginBottom:16 }}>
        {/* Sale numbers */}
        <Card>
          <h3 style={{ marginBottom:12, fontSize:15 }}>📦 Recent Sale Numbers</h3>
          <div style={{ display:'flex', gap:8, flexWrap:'wrap' }}>
            {stats?.recent_sales?.length > 0
              ? stats.recent_sales.map(s => (
                  <span key={s.sale_no} style={{ background:'#dbeafe', color:'#1e40af', padding:'4px 14px', borderRadius:99, fontSize:13, fontWeight:600 }}>
                    Sale {s.sale_no}
                    <span style={{ fontSize:11, fontWeight:400, color:'#60a5fa', marginLeft:4 }}>({s.lot_count} lots)</span>
                  </span>
                ))
              : <span style={{ color:'#aaa', fontSize:13 }}>No sales imported yet. Upload a Catalogue first.</span>
            }
          </div>
        </Card>

        {/* Grades */}
        <Card>
          <h3 style={{ marginBottom:12, fontSize:15 }}>📊 Grades in Catalogue</h3>
          <div style={{ display:'flex', gap:6, flexWrap:'wrap' }}>
            {stats?.grades?.length > 0
              ? stats.grades.map(g => (
                  <span key={g.grade} style={{ background:'#f0fdf4', border:'1px solid #bbf7d0', color:'#166534', padding:'3px 10px', borderRadius:99, fontSize:12, fontWeight:600 }}>
                    {g.grade} <span style={{ color:'#86efac', fontSize:11 }}>({g.count})</span>
                  </span>
                ))
              : <span style={{ color:'#aaa', fontSize:13 }}>Import catalogue to see grades</span>
            }
          </div>
        </Card>
      </div>

      {/* Top gardens */}
      {stats?.top_gardens?.length > 0 && (
        <Card style={{ marginBottom:16 }}>
          <h3 style={{ marginBottom:12, fontSize:15 }}>🌿 Top Gardens (by lots)</h3>
          <div style={{ display:'flex', gap:6, flexWrap:'wrap' }}>
            {stats.top_gardens.map(g => (
              <span key={g.garden} style={{ background:'#fefce8', border:'1px solid #fde68a', color:'#92400e', padding:'3px 10px', borderRadius:99, fontSize:12, fontWeight:600 }}>
                {g.garden} <span style={{ fontSize:11, color:'#f59e0b' }}>({g.count})</span>
              </span>
            ))}
          </div>
        </Card>
      )}

      {/* Import History */}
      <Card>
        <h3 style={{ marginBottom:12, fontSize:15 }}>📜 Import History</h3>
        <div style={{ overflowX:'auto' }}>
          <table style={{ width:'100%', borderCollapse:'collapse', fontSize:13 }}>
            <thead>
              <tr style={{ background:'#f0f4f8' }}>
                {['Type','File','Sale No','Imported','Skipped','Date'].map(h => (
                  <th key={h} style={{ padding:'7px 10px', textAlign:'left', fontWeight:600, color:'#444', borderBottom:'2px solid #e2e8f0', whiteSpace:'nowrap' }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {logs.length === 0
                ? <tr><td colSpan={6} style={{ padding:20, textAlign:'center', color:'#aaa' }}>No imports yet. Upload a Catalogue to begin.</td></tr>
                : logs.map((l, i) => (
                  <tr key={i} style={{ borderBottom:'1px solid #f0f4f8' }}>
                    <td style={{ padding:'7px 10px' }}>
                      <span style={{ background:l.file_type==='catalogue'?'#dbeafe':'#dcfce7', color:l.file_type==='catalogue'?'#1e40af':'#166534', padding:'2px 8px', borderRadius:99, fontSize:11, fontWeight:600 }}>
                        {l.file_type}
                      </span>
                    </td>
                    <td style={{ padding:'7px 10px', fontSize:12 }}>{l.filename}</td>
                    <td style={{ padding:'7px 10px', fontWeight:600 }}>{l.sale_no || '—'}</td>
                    <td style={{ padding:'7px 10px', color:'#1a7a4a', fontWeight:700 }}>{l.rows_imported}</td>
                    <td style={{ padding:'7px 10px', color:l.rows_skipped>0?'#c0392b':'#888' }}>{l.rows_skipped}</td>
                    <td style={{ padding:'7px 10px', color:'#888' }}>{new Date(l.imported_at).toLocaleString('en-IN')}</td>
                  </tr>
                ))
              }
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
}
